import json,re,difflib
o={x['id']:x for x in json.load(open('$S/originals.json'))}
a=json.load(open('$S/tr/opus.json')); b={x['id']:x['text'] for x in json.load(open('$S/tr/sonnet.json'))}
def key(i): return i.split(':')[-1]
A={}
for i in o: A[i]=a[key(i)]
num=lambda t: sorted(re.findall(r'\d+(?:[.,]\d+)?', t))
unit=lambda t: sorted(re.findall(r'(?:%|mm|cm|km|m\b|°|degrees?|percent|inch(?:es)?|feet|ft|N\b|kg|:\d+)', t.lower()))
bad=[];low=[]
for i in o:
    ta,tb=A[i],b[i]
    ok_n=num(ta)==num(tb); ok_u=unit(ta)==unit(tb)
    r=difflib.SequenceMatcher(None,ta.lower(),tb.lower()).ratio()
    if not ok_n or not ok_u: bad.append((i,ok_n,ok_u,ta,tb))
    elif r<0.6: low.append((i,round(r,2),ta,tb))
print("numbers/units differ:",len(bad)," low-similarity only:",len(low))
for i,n,u,ta,tb in bad: print("\n",i,"num_ok",n,"unit_ok",u,"\n O:",ta[:230],"\n S:",tb[:230])
print("\n--- low similarity ---")
for i,r,ta,tb in low: print("\n",i,r,"\n O:",ta[:200],"\n S:",tb[:200])
json.dump({'bad':[x[0] for x in bad],'low':[x[0] for x in low]},open('$S/tr/compare.json','w'))
PY

